 static void initializeCookies(Context c){try{Class<?> v=Class.forName("e.e.a.v0");if(v.getField("b").get(null)!=null)return;android.content.SharedPreferences p=PreferenceManager.getDefaultSharedPreferences(c);if(p.getBoolean("nologin",false))return;String saved=p.getString("save_cookie","");if(!saved.isEmpty())v.getField("b").set(null,v.getMethod("b",String.class).invoke(null,saved));}catch(Exception ignored){}}
