 public static void bind(Object f,View root){if(root==null)return;try{initializeCookies(root.getContext());Bundle data=(Bundle)f.getClass().getField("i0").get(f);if(data==null)return;String id=data.getString("videoId","");if(!id.matches("(?:sm|nm|so)?[0-9]+"))return;try{JSONObject w=(JSONObject)Class.forName("e.e.a.ModernPlayback").getField("latestWatch").get(null);if(w!=null&&w.optJSONObject("video")!=null&&id.equals(w.optJSONObject("video").optString("id")))capture(w,data);}catch(Exception ignored){}View description=root.findViewById(0x7f08007a);if(description==null||!(description.getParent() instanceof LinearLayout))return;View nativeFollow=root.findViewById(0x7f0801c7);if(nativeFollow!=null){nativeFollow.setVisibility(8);if(nativeFollow.getLayoutParams()!=null)nativeFollow.getLayoutParams().width=0;}View bar=root.findViewById(0x7f0801c8);if(bar instanceof LinearLayout){LinearLayout holder=(LinearLayout)bar;View previous=holder.findViewWithTag("nicoid_follow");if(previous==null){JSONObject owner=json(data,"details_owner");String user=owner.optString("id",data.getString("videoUserId",""));if(user.matches("[0-9]+")){FollowIcon b=new FollowIcon(root.getContext());b.setTag("nicoid_follow");LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(root.getContext(),48),dp(root.getContext(),48));lp.gravity=Gravity.CENTER_VERTICAL;lp.setMargins(dp(root.getContext(),8),0,dp(root.getContext(),8),0);holder.addView(b,lp);b.setVisibility(PreferenceManager.getDefaultSharedPreferences(root.getContext()).getBoolean(DetailSettings.FOLLOW,true)?0:8);if(b.getVisibility()==0)followButton(b,user,owner);}}else previous.setVisibility(PreferenceManager.getDefaultSharedPreferences(root.getContext()).getBoolean(DetailSettings.FOLLOW,true)?0:8);}LinearLayout parent=(LinearLayout)description.getParent();if(parent.findViewWithTag("nicoid_details")!=null)return;LinearLayout box=PanelUi.column(root.getContext());box.setTag("nicoid_details");parent.addView(box);box.addView(text(root.getContext(),tr("シリーズ","Series","系列"),18));LinearLayout series=PanelUi.column(root.getContext());box.addView(series);JSONObject cached=json(data,"details_series");if(cached.optString("id").matches("[0-9]+"))renderSeries(series,cached);else loadSeries(series,id);box.addView(text(root.getContext(),tr("親作品・子作品","Parent and child works","父作品與子作品"),18));for(String k:new String[]{"parents","children"}){LinearLayout group=PanelUi.column(root.getContext());box.addView(group);new TreePage(group,id,k).load();}}catch(Exception ignored){}}
