 private static void loadSeries(LinearLayout box,String id){box.removeAllViews();TextView loading=text(box.getContext(),tr("読み込み中…","Loading…","載入中…"),14);box.addView(loading);NetworkTask task=new NetworkTask();scope(box,task);box.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener(){public void onViewDetachedFromWindow(View v){}public void onViewAttachedToWindow(View v){if(task.cancelled()&&loading.getParent()!=null){box.removeOnAttachStateChangeListener(this);loadSeries(box,id);}}});task.start(WORK,()->{try{JSONObject d=watchData(request("https://www.nicovideo.jp/watch/"+id+"?responseType=json","GET",true,task));JSONObject s=d.optJSONObject("series");if(!d.has("video"))throw new IOException();MAIN.post(()->{if(task.cancelled())return;box.removeAllViews();if(s==null||!s.optString("id").matches("[0-9]+"))box.addView(text(box.getContext(),tr("シリーズに登録されていません","Not part of a series","未加入系列"),14));else renderSeries(box,s);});}catch(Exception e){android.util.Log.w("NicoidDetails","Series metadata request failed: "+e.getClass().getSimpleName()+" "+(e instanceof IOException?e.getMessage():"invalid response"));MAIN.post(()->{if(task.cancelled())return;loading.setText(tr("シリーズ情報を取得できませんでした","Unable to load series","無法載入系列資訊"));Button retry=button(box.getContext(),tr("再試行","Retry","重試"));retry.setOnClickListener(v->loadSeries(box,id));box.addView(retry);});}});}
 private static void renderSeries(LinearLayout box,JSONObject s){box.addView(text(box.getContext(),s.optString("title"),16));JSONObject videos=s.optJSONObject("video");if(videos!=null)for(String k:new String[]{"prev","next"}){JSONObject row=videos.optJSONObject(k);if(row!=null)videoRow(box,row,k.equals("prev")?tr("前の動画","Previous video","上一部影片"):tr("次の動画","Next video","下一部影片"));}new SeriesPage(box,s.optString("id"));}
 static String target(JSONObject item){return DetailData.target(item);}
